import { useCallback, useEffect, useRef, useState } from 'react';
import type { DragEvent, FormEvent, ReactNode } from 'react';
import { ArrowClockwise, ArrowRight, ArrowSquareOut, ArrowUp, BookOpen, BracketsCurly, CaretRight, ChatCircleText, Check, CheckCircle, CircleNotch, Database, DownloadSimple, FilePdf, FileMagnifyingGlass, Files, FileText, Flask, GearSix, GitDiff, Info, Link, List, ListBullets, LockKey, MagnifyingGlass, PencilSimple, Plus, Robot, Scales, SealCheck, ShieldCheck, SquaresFour, Stack, TestTube, Trash, UploadSimple, WarningCircle, X } from '@phosphor-icons/react';
import type { Icon } from '@phosphor-icons/react';
import { ApiError, defaultEngine, engineIsAvailable, isCancelled, paperPagePreviewUrl, post, qaDisplayAnswer, request } from './api';
import { extractionRequestScope } from './extractionScope';
import type { CitationQuote, CompareResult, Engine, Evidence, Experiment, ExperimentHistoryEntry, ExtractionCandidate, FieldQuote, Health, Paper, PaperDetail, QAResult, ReportSummary, Trace, VerificationDetail, VerifyEngine, VerifyResult } from './api';

type Page = 'library'|'qa'|'compare'|'verify'|'settings';
type Conversation = {id:string;question:string;result:QAResult;paper_ids:string[]};
type EvidenceOrigin = {label:string;papers:Paper[];historical:boolean};
type EvidenceQuoteContext = {label:string;quotes:FieldQuote[];kind?:'citation'};
const nav:{id:Page;label:string;icon:Icon}[]=[{id:'library',label:'文献库',icon:Files},{id:'qa',label:'智能问答',icon:ChatCircleText},{id:'compare',label:'对比分析',icon:GitDiff},{id:'verify',label:'结论核验',icon:SealCheck},{id:'settings',label:'系统设置',icon:GearSix}];
const comparabilityNames={direct:'可直接比较',conditional:'有条件比较',incomparable:'不可比较',insufficient:'信息不足'};
const verdictNames={consistent:'结果一致',different:'存在数值差异',conditions_differ:'实验条件不一致',potential_conflict:'潜在结论冲突',insufficient:'证据不足'};
const fieldNames:Record<string,string>={task:'研究任务',method:'方法',dataset:'数据集',split:'数据划分',sample_size:'样本量',metric:'评价指标',value:'实验数值',unit:'单位',conditions:'实验条件'};
const verifyNames={supported:'原文支持',partial:'部分支持',insufficient:'证据不足',contradicted:'与原文不符'};
const modelVerifyNames={supported:'模型判断 · 原文支持（待复核）',partial:'模型判断 · 部分支持（待复核）',insufficient:'模型判断 · 证据不足',contradicted:'模型判断 · 与原文不符（待复核）'};
export const engineNames:Record<string,string>={local:'本地证据检索',llm:'大模型增强问答',rules:'规则分析',offline:'本地保守核验'};
export function ResearchEngineOptions({purpose,providers}:{purpose:'qa'|'verify';providers?:Health['providers']}){
 return <><option value="local">{purpose==='qa'?'本地证据检索':'本地保守核验 · 不调用模型'}</option><option value="llm" disabled={!engineIsAvailable('llm',providers)}>{purpose==='qa'?'大模型增强问答':'模型语义核验'}{!providers?.llm_configured?' · 未配置':purpose==='verify'?' · 将调用模型':''}</option></>;
}
function formatDate(value:string){const date=new Date(value);return Number.isNaN(date.valueOf())?value:date.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});}
function errorText(error:unknown){return error instanceof Error?error.message:'操作未完成，请重试。';}
function loadScope(){try{const value=JSON.parse(localStorage.getItem('evidencelab.paper-scope')??'[]');return Array.isArray(value)?[...new Set(value.filter((id:unknown):id is string=>typeof id==='string'))].slice(0,30):[];}catch{return [];}}
function sameScope(left:string[],right:string[]){return left.length===right.length&&left.every(id=>right.includes(id));}
const providerStatusNames={unconfigured:'未配置',untested:'已配置 · 未验证连接',available:'最近调用成功',failed:'最近调用失败'};
const operationNames:Record<string,string>={qa:'问答',compare:'比较分析',verify:'结论核验',extract:'候选提取',candidate:'候选审阅',save:'保存人工修正',upload:'导入文献',delete:'删除文献',demo:'载入演示',report:'读取历史报告',history:'读取实验修改历史'};
function Spinner(){return <CircleNotch size={17} className="spin"/>;}
function Tag({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`tag ${tone}`}>{children}</span>;}
function Empty({icon:Icon,title,children}:{icon:Icon;title:string;children:ReactNode}){return <div className="empty-state"><span className="empty-icon"><Icon size={29}/></span><h3>{title}</h3><div className="muted">{children}</div></div>;}
function Modal({title,children,onClose,className='',error}:{title:string;children:ReactNode;onClose:()=>void;className?:string;error?:string|null}){
 const ref=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const dialog=ref.current;dialog?.showModal();return()=>dialog?.close();},[]);
 return <dialog ref={ref} className={`modal ${className}`} aria-label={title} onCancel={e=>{e.preventDefault();onClose();}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal-inner"><div className="modal-heading"><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={onClose}><X size={21}/></button></div>{error&&<div className="alert error modal-error" role="alert"><WarningCircle size={18}/><span>{error}</span></div>}{children}</div></dialog>;
}
function Traces({traces,onEvidence}:{traces:Trace[];onEvidence:(ids:string[])=>void}){
 if(!traces.length)return null;
 return <details className="trace-panel"><summary><Robot size={17}/>多阶段分析工作流 <span>{traces.length} 个步骤</span><CaretRight className="details-caret" size={15}/></summary><div className="trace-list">{traces.map((trace,index)=><div className="trace-item" key={`${trace.agent}-${index}`}><span className={`trace-marker ${trace.status}`}>{trace.status==='completed'?<Check size={13}/>:trace.status==='failed'?<X size={13}/>:<span>·</span>}</span><div><div className="row between"><strong>{trace.agent}{trace.kind&&<small className="trace-kind">{trace.kind==='rule'||trace.kind==='rules'?'规则步骤':trace.kind==='llm'?'模型步骤':trace.kind}</small>}</strong><span className="micro muted">{trace.duration_ms} ms · {trace.status==='completed'?'完成':trace.status==='failed'?'失败':'已跳过'}</span></div><p>{trace.summary}</p>{(trace.input||trace.output)&&<dl className="trace-io">{trace.input&&<div><dt>输入摘要</dt><dd><pre>{JSON.stringify(trace.input,null,2)}</pre></dd></div>}{trace.output&&<div><dt>输出摘要</dt><dd><pre>{JSON.stringify(trace.output,null,2)}</pre></dd></div>}</dl>}{trace.evidence_ids.length>0&&<button className="text-button small" onClick={()=>onEvidence(trace.evidence_ids)}><Link size={13}/>{trace.evidence_ids.length} 条关联证据</button>}</div></div>)}</div></details>;
}
function WarningNotes({warnings}:{warnings:string[]}){return warnings.length>0?<div className="warning-notes">{warnings.map((item,index)=><p key={index}><Info size={15}/>{item}</p>)}</div>:null;}
type EvidenceCardsProps = {citations:Evidence[];papers:Paper[];quotes?:CitationQuote[];onOpen:(evidence:Evidence,list?:Evidence[])=>void;onOpenQuote?:(evidence:Evidence,list:Evidence[],quotes:CitationQuote[])=>void};
function EvidenceCards({citations,papers,quotes=[],onOpen,onOpenQuote}:EvidenceCardsProps){return <div className="citation-grid">{citations.map((item,index)=>{const selected=quotes.filter(quote=>quote.id===item.id);return <button className="citation-card" key={item.id} onClick={()=>selected.length&&onOpenQuote?onOpenQuote(item,citations,quotes):onOpen(item,citations)}><div className="row between"><span className="citation-number">{String(index+1).padStart(2,'0')}</span><span className="micro muted">第 {item.page} 页 <ArrowSquareOut size={12}/></span></div>{selected.length?<>{selected.map((quote,quoteIndex)=><p className="selected-citation-quote" key={quoteIndex}>{quote.quote}</p>)}<small className="citation-protocol-note">{selected.every(quote=>quote.protocol==='server_bound_fragment')?'服务器保留的原文片段':'已核对的原文引文'} · 点击查看完整上下文</small></>:<p>{item.text}</p>}<div className="citation-source"><FileText size={13}/><span>{papers.find(p=>p.id===item.paper_id)?.title??'来源文献'}</span></div></button>;})}</div>;}
function PaperPagePreview({paperId,page,fileUrl}:{paperId:string;page:number;fileUrl:string}){
 const [state,setState]=useState<'loading'|'ready'|'error'>('loading');
 const url=paperPagePreviewUrl(paperId,page);
 return <div className="pdf-preview"><div className="section-label"><FilePdf size={15}/>原文页面预览 · 第 {page} 页</div>{state==='error'||!url?<div className="alert warning" role="status"><WarningCircle size={17}/><div><p>页面图像暂时无法加载，保存的原文引文和页码仍可核查。</p><a className="text-button small" href={fileUrl} target="_blank" rel="noreferrer">打开原始文献<ArrowSquareOut size={13}/></a></div></div>:<>{state==='loading'&&<div className="page-preview-loading" role="status"><Spinner/><span>正在载入原文页面预览…</span></div>}<a href={url} target="_blank" rel="noreferrer" aria-label={`查看第 ${page} 页原文大图`}><img className="paper-page-image" src={url} alt={`原始文献第 ${page} 页页面预览`} onLoad={()=>setState('ready')} onError={()=>setState('error')}/></a><p className="micro muted">点击页面可打开大图；完整 PDF 可通过上方“打开原始文献”查看。</p></>}</div>;
}
function ModelVerification({result,title='逐项模型核验',local=false,citations,papers,onOpen,onOpenQuote}:{result:VerificationDetail;title?:string;local?:boolean}&Omit<EvidenceCardsProps,'quotes'>){
 return <section className={`model-verification ${result.status==='failed'?'failed':''}`}><div className="row between model-verdict-heading"><h3><ShieldCheck size={17}/>{title}</h3><Tag tone={result.status==='failed'?'amber':result.verdict==='supported'?'green':result.verdict==='contradicted'?'red':'amber'}>{result.status==='failed'?'模型核验未完成':local?verifyNames[result.verdict]:modelVerifyNames[result.verdict]}</Tag></div><p className="model-verification-boundary">{local?'本次仅检索候选原文并保守返回证据不足，未调用模型作语义判断。':'以下为待人工复核的模型判断，不是系统认证或科研真伪证明。即使引文准确，模型仍可能错配对象、数值或实验条件。'}</p>{!!result.safety_gaps?.length&&<div className="alert warning"><WarningCircle size={17}/><div><strong>来源检查未通过 · 已降级为证据不足</strong><WarningNotes warnings={result.safety_gaps}/></div></div>}{result.status==='failed'?<p className="verification-failure">{result.explanation}</p>:result.claim_checks?.length?<div className="claim-checks">{result.claim_checks.map((check,index)=><details key={index} className="claim-check" open={result.claim_checks?.length===1||!!check.safety_gaps?.length}><summary><span>{check.claim}</span><Tag tone={check.verdict==='supported'?'green':check.verdict==='contradicted'?'red':'amber'}>{modelVerifyNames[check.verdict]}</Tag></summary>{check.safety_gaps?.length?<div className="alert warning"><WarningCircle size={17}/><div><strong>来源检查未通过 · 本项暂不能支持或反驳</strong><WarningNotes warnings={check.safety_gaps}/></div></div>:<p>模型判断（待复核）：{check.explanation}</p>}{check.citation_quotes.length?<EvidenceCards citations={citations.filter(item=>check.citation_quotes.some(quote=>quote.id===item.id))} papers={papers} quotes={check.citation_quotes} onOpen={onOpen} onOpenQuote={onOpenQuote}/>:<p className="muted">本项没有可用于支持或反驳的原文依据。</p>}</details>)}</div>:<p className="verification-explanation">{local?'':'模型判断（待复核）：'}{result.explanation}</p>}</section>;
}

export default function App(){
 const [page,setPage]=useState<Page>('library');
 const [mobileNav,setMobileNav]=useState(false);
 const [papers,setPapers]=useState<Paper[]>([]);
 const [selected,setSelected]=useState<string[]>(loadScope);
 const [scopeOpen,setScopeOpen]=useState(()=>loadScope().length===0);
 const [health,setHealth]=useState<Health|null>(null);
 const [settings,setSettings]=useState<Record<string,unknown>|null>(null);
 const [initialLoading,setInitialLoading]=useState(true);
 const [busy,setBusy]=useState<string|null>(null);
 const operation=useRef<{id:string;controller:AbortController}|null>(null);
 const detailRequest=useRef<AbortController|null>(null);
 const evidenceRequest=useRef(0);
 const [elapsed,setElapsed]=useState(0);
 const [error,setError]=useState<string|null>(null);
 const [notice,setNotice]=useState<string|null>(null);
 const [search,setSearch]=useState('');
 const [selectedOnly,setSelectedOnly]=useState(false);
 const [listView,setListView]=useState(false);
 const [dragging,setDragging]=useState(false);
 const fileInput=useRef<HTMLInputElement>(null);
 const detailCache=useRef<Record<string,PaperDetail>>({});
 const [detail,setDetail]=useState<PaperDetail|null>(null);
 const [detailLoading,setDetailLoading]=useState<string|null>(null);
 const [deletePaper,setDeletePaper]=useState<Paper|null>(null);
 const [showDemo,setShowDemo]=useState(false);
 const [activeEvidence,setActiveEvidence]=useState<{item:Evidence;list:Evidence[];fieldContext?:EvidenceQuoteContext;origin?:EvidenceOrigin}|null>(null);
 const [originalState,setOriginalState]=useState<'checking'|'available'|'missing'|'unavailable'>('checking');
 const [originalError,setOriginalError]=useState('');
 const [question,setQuestion]=useState('');
 const [engine,setEngine]=useState<Engine>('local');
 const engineDefaultsApplied=useRef(false);
 const [conversations,setConversations]=useState<Conversation[]>([]);
 const [activeQuestion,setActiveQuestion]=useState<string|null>(null);
 const [comparison,setComparison]=useState<CompareResult|null>(null);
 const [comparisonStale,setComparisonStale]=useState(false);
 const [comparisonSnapshot,setComparisonSnapshot]=useState(false);
 const [reports,setReports]=useState<ReportSummary[]>([]);
 const [reportError,setReportError]=useState<string|null>(null);
 const [candidateSelection,setCandidateSelection]=useState<Record<string,string[]>>({});
 const [editExperiment,setEditExperiment]=useState<Experiment|null>(null);
 const [manualCandidate,setManualCandidate]=useState(false);
 const [manualQuotes,setManualQuotes]=useState<Record<string,Record<string,string>>>({});
 const [editRevision,setEditRevision]=useState<string|null>(null);
 const [editConflict,setEditConflict]=useState(false);
 const [experimentHistory,setExperimentHistory]=useState<{current:Experiment;entries:ExperimentHistoryEntry[];sources:Evidence[];paper:Paper}|null>(null);
 const [editSources,setEditSources]=useState<Evidence[]>([]);
 const [editFieldEvidence,setEditFieldEvidence]=useState<Record<string,string[]>>({});
 const [editSourceField,setEditSourceField]=useState('method');
 const [editSourceQuery,setEditSourceQuery]=useState('');
 const [claim,setClaim]=useState('');
 const [verifyEngine,setVerifyEngine]=useState<VerifyEngine>('local');
 const [verification,setVerification]=useState<(VerifyResult&{claim:string;paper_ids:string[]})|null>(null);
 const [detailTab,setDetailTab]=useState<'experiments'|'evidence'>('experiments');
 const [reparse,setReparse]=useState(false);
 const [extractPages,setExtractPages]=useState('');
 const [extractMaxResults,setExtractMaxResults]=useState('12');
 const readyPapers=papers.filter(p=>p.status==='ready');
 const selectedPapers=papers.filter(p=>selected.includes(p.id));
 const filteredPapers=papers.filter(p=>(!selectedOnly||selected.includes(p.id))&&`${p.title} ${p.filename} ${p.authors.join(' ')}`.toLowerCase().includes(search.toLowerCase()));
 const allSelected=readyPapers.length>0&&readyPapers.slice(0,30).every(p=>selected.includes(p.id));
 const activeConversation=conversations.find(item=>item.id===activeQuestion);
 const currentNav=nav.find(item=>item.id===page)!;
 const totalEvidence=papers.reduce((sum,p)=>sum+p.evidence_count,0);
 const totalExperiments=papers.reduce((sum,p)=>sum+p.experiment_count,0);
 const evidencePaper=activeEvidence?(activeEvidence.origin?.papers??papers).find(p=>p.id===activeEvidence.item.paper_id):undefined;
 const changePage=(value:Page)=>{setPage(value);setMobileNav(false);setError(null);};
 const refresh=useCallback(async()=>{
  const results=await Promise.allSettled([request<Paper[]>('/papers'),request<Health>('/health'),request<Record<string,unknown>>('/settings'),request<ReportSummary[]>('/reports')]);
  if(results[0].status==='fulfilled'){setPapers(results[0].value);setSelected(ids=>ids.filter(id=>results[0].status==='fulfilled'&&results[0].value.some(p=>p.id===id&&p.status==='ready')));}else setError(`无法读取文献库：${errorText(results[0].reason)}。请确认后端服务已启动。`);
  if(results[1].status==='fulfilled')setHealth(results[1].value);else setHealth(null);
  if(results[2].status==='fulfilled')setSettings(results[2].value);else setSettings(null);
  if(results[3].status==='fulfilled'){setReports(results[3].value);setReportError(null);}else setReportError(errorText(results[3].reason));
  setInitialLoading(false);
 },[]);
 useEffect(()=>{void refresh();},[refresh]);
 useEffect(()=>{try{localStorage.setItem('evidencelab.paper-scope',JSON.stringify(selected));}catch{/* Scope remains available in memory when browser storage is unavailable. */}},[selected]);
 useEffect(()=>{if(!selected.length)setScopeOpen(true);},[selected.length]);
 useEffect(()=>{setExtractPages('');setExtractMaxResults('12');setReparse(false);},[detail?.id]);
 useEffect(()=>{if(!busy){setElapsed(0);return;}const started=Date.now();const timer=setInterval(()=>setElapsed(Math.floor((Date.now()-started)/1000)),1000);return()=>clearInterval(timer);},[busy]);
 useEffect(()=>()=>{operation.current?.controller.abort();detailRequest.current?.abort();evidenceRequest.current++;},[]);
 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(null),6000);return()=>clearTimeout(timer);},[notice]);
 useEffect(()=>{if(health&&!engineDefaultsApplied.current){engineDefaultsApplied.current=true;setEngine(defaultEngine(health.providers));setVerifyEngine(defaultEngine(health.providers));}},[health]);
 useEffect(()=>{if(!engineIsAvailable(engine,health?.providers))setEngine('local');},[health,engine]);
 useEffect(()=>{if(!engineIsAvailable(verifyEngine,health?.providers))setVerifyEngine('local');},[health,verifyEngine]);
 useEffect(()=>{
  if(!activeEvidence)return;const id=activeEvidence.item.paper_id,controller=new AbortController();
  if(!papers.some(p=>p.id===id&&p.file_url)){setOriginalState('missing');setOriginalError('来源文献已不在当前文献库，无法打开原始文件。保存的摘录与字段引文仍可阅读。');return;}
  setOriginalState('checking');setOriginalError('');
  void request(`/papers/${id}/file`,{responseType:'probe',headers:{Range:'bytes=0-0'},signal:controller.signal,timeoutMs:10000}).then(()=>setOriginalState('available')).catch(err=>{if(isCancelled(err))return;setOriginalState(err instanceof ApiError&&[404,409].includes(err.status)?'missing':'unavailable');setOriginalError(`${errorText(err)} 保存的摘录仍保留在下方。`);});
  return()=>controller.abort();
 },[activeEvidence?.item.paper_id,papers]);
 const togglePaper=(id:string)=>setSelected(ids=>ids.includes(id)?ids.filter(item=>item!==id):ids.length<30?[...ids,id]:ids);
 function beginOperation(kind:string){if(operation.current)return null;const token={id:crypto.randomUUID(),controller:new AbortController()};operation.current=token;setBusy(kind);setError(null);return token;}
 function finishOperation(token:{id:string}){if(operation.current?.id===token.id){operation.current=null;setBusy(null);}}
 function operationError(err:unknown){if(!isCancelled(err))setError(errorText(err));}
 function cancelOperation(){operation.current?.controller.abort();operation.current=null;setBusy(null);setNotice('已停止等待本次结果。服务器可能仍在处理；可刷新文献详情或报告查看状态。');}
 async function getDetail(id:string,force=false){if(!force&&detailCache.current[id])return detailCache.current[id];const data=await request<PaperDetail>(`/papers/${id}`);detailCache.current[id]=data;return data;}
 async function showDetail(paper:Paper){detailRequest.current?.abort();const controller=new AbortController();detailRequest.current=controller;setDetailLoading(paper.id);setError(null);try{const data=await request<PaperDetail>(`/papers/${paper.id}`,{signal:controller.signal});if(detailRequest.current!==controller)return;detailCache.current[data.id]=data;setDetail(data);setDetailTab('experiments');}catch(err){operationError(err);}finally{if(detailRequest.current===controller)setDetailLoading(null);}}
 async function openEvidenceIds(ids:string[],paperId?:string,scopeIds?:string[],fieldContext?:{label:string;quotes:FieldQuote[]}){
  if(!ids.length){setNotice('此字段尚未关联原文证据。');return;}
  const scope=paperId?[paperId]:scopeIds??selected;
  if(!scope.length){setNotice('请先选择文献范围，再查看关联证据。');return;}
  const token=++evidenceRequest.current;
  try{const results=await Promise.allSettled([...new Set(scope)].map(id=>getDetail(id)));if(token!==evidenceRequest.current)return;const found=[...new Map(results.flatMap(item=>item.status==='fulfilled'?[...item.value.evidence,...(item.value.extraction_candidates??[]).flatMap(candidate=>candidate.source_evidence??[])]:[]).filter(item=>ids.includes(item.id)).map(item=>[item.id,item])).values()];if(found.length){setActiveEvidence({item:found[0],list:found,fieldContext});if(found.length<ids.length)setNotice(`已定位 ${found.length} 条证据；其余来源无法读取，请刷新文献后核查。`);}else setError('无法在该分析的文献范围内定位证据。文献可能已删除，或服务连接失败，请刷新后重试。');}catch(err){operationError(err);}
 }
 function openEvidence(item:Evidence,list:Evidence[]=[item],origin?:EvidenceOrigin){evidenceRequest.current++;setActiveEvidence({item,list,origin});}
 function openCitedEvidence(item:Evidence,list:Evidence[],quotes:CitationQuote[]){evidenceRequest.current++;setActiveEvidence({item,list,fieldContext:{label:'本次判断选用的原文引文',quotes,kind:'citation'}});}
 async function uploadFiles(files:File[]){
  if(!files.length||busy)return;
  if(files.length>10){setError('每次最多上传 10 个文件，请分批导入。');if(fileInput.current)fileInput.current.value='';return;}
  const valid=files.filter(file=>/\.(pdf|txt|md)$/i.test(file.name)&&file.size>0&&file.size<=32*1024*1024);
  const rejected=files.filter(file=>!valid.includes(file));
  if(!valid.length){setError('请上传非空 PDF、TXT 或 Markdown，每个文件不能超过 32 MB。');if(fileInput.current)fileInput.current.value='';return;}
  const token=beginOperation('upload');if(!token)return;const form=new FormData();valid.forEach(file=>form.append('files',file));
  try{const data=await request<{papers:Paper[];errors:{filename:string;error:string}[]}>('/papers/upload',{method:'POST',body:form,signal:token.controller.signal,timeoutMs:180000});await refresh();setSelected(ids=>[...new Set([...ids,...data.papers.filter(p=>p.status==='ready').map(p=>p.id)])].slice(0,30));const errors=[...rejected.map(file=>`${file.name}：${file.size===0?'文件为空':file.size>32*1024*1024?'超过 32 MB':'不支持此格式'}`),...data.errors.map(item=>`${item.filename}：${item.error}`)];if(errors.length)setError(errors.join('\n'));if(data.papers.length)setNotice(`已处理 ${data.papers.length} 篇文献；相同内容自动复用已有记录。可打开详情检查证据与实验。`);}catch(err){operationError(err);}finally{finishOperation(token);if(fileInput.current)fileInput.current.value='';}
 }
 async function seedDemo(){if(busy)return;const token=beginOperation('demo');if(!token)return;setShowDemo(false);try{const data=await post<{papers:Paper[]}>('/demo/seed',{},{signal:token.controller.signal,timeoutMs:90000});await refresh();setSelected(data.papers.filter(p=>p.status==='ready').map(p=>p.id));setNotice('已载入 3 篇合成演示文献。所有示例均已标注，不用于真实科研判断。');}catch(err){operationError(err);}finally{finishOperation(token);}}
 async function removePaper(){if(!deletePaper||busy)return;const paper=deletePaper,token=beginOperation('delete');if(!token)return;try{await request(`/papers/${paper.id}`,{method:'DELETE',signal:token.controller.signal});delete detailCache.current[paper.id];if(detail?.id===paper.id)setDetail(null);setComparison(null);setVerification(null);setConversations(items=>items.filter(item=>!item.paper_ids.includes(paper.id)));await refresh();setDeletePaper(null);setNotice('文献及其证据已删除。');}catch(err){operationError(err);}finally{finishOperation(token);}}
 async function extractPaper(mode:'rule'|'llm'){
  if(!detail||busy)return;let extractionScope;try{extractionScope=extractionRequestScope(extractPages,extractMaxResults,detail.page_count);}catch(err){operationError(err);return;}const paperId=detail.id;const token=beginOperation('extract');if(!token)return;
  try{const data=await post<PaperDetail>(`/papers/${paperId}/extract`,{mode,reparse,...extractionScope},{signal:token.controller.signal,timeoutMs:mode==='llm'?610000:90000});detailCache.current[data.id]=data;setDetail(current=>current?.id===data.id?data:current);await refresh();setNotice('已生成限定范围的候选实验；结果数量有上限，不表示全文完整。请核对配置、数值与原文后接受。');}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function reviewCandidate(candidate:ExtractionCandidate,action:'accept'|'reject'){
  if(busy)return;const token=beginOperation('candidate');if(!token)return;
  const chosen=candidateSelection[candidate.id]??candidate.experiments.map(exp=>exp.id);
  try{const data=await post<PaperDetail>(`/papers/${candidate.paper_id}/extraction-candidates/${candidate.id}/${action}`,action==='accept'?{experiment_ids:chosen}:{},{signal:token.controller.signal});detailCache.current[data.id]=data;setDetail(current=>current?.id===data.id?data:current);if(action==='accept')setComparisonStale(true);await refresh();setNotice(action==='accept'?'已接受所选候选实验；已存在的同项实验不会重复添加。':'已拒绝本次候选，既有实验未改变。');}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function askQuestion(event:FormEvent){
  event.preventDefault();if(!question.trim()||!selected.length||busy)return;const submitted=question.trim(),scope=[...selected],submittedEngine=engine;const token=beginOperation('qa');if(!token)return;
  try{const result=await post<QAResult>('/qa',{question:submitted,paper_ids:scope,engine:submittedEngine},{signal:token.controller.signal,timeoutMs:submittedEngine==='local'?30000:400000});const id=crypto.randomUUID();setConversations(items=>[{id,question:submitted,result,paper_ids:scope},...items]);setActiveQuestion(id);setQuestion(value=>value.trim()===submitted?'':value);}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function runComparison(){
  if(selected.length<2||busy)return;const scope=[...selected],token=beginOperation('compare');if(!token)return;
  try{const data=await post<CompareResult>('/compare',{paper_ids:scope},{signal:token.controller.signal,timeoutMs:90000});setComparison(data);setComparisonSnapshot(false);setComparisonStale(false);await refresh();}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function loadReport(id:string){
  if(busy)return;const token=beginOperation('report');if(!token)return;
  try{const data=await request<CompareResult>(`/reports/${id}`,{signal:token.controller.signal});setComparison(data);setComparisonSnapshot(true);setComparisonStale(data.stale===true);setSelected(data.papers.filter(p=>papers.some(current=>current.id===p.id&&current.status==='ready')).map(p=>p.id));setNotice('已打开只读报告快照，保留当时的实验、判断与原文摘录。');}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function downloadReport(id:string,format:'markdown'|'json',historical=false){
  if(busy)return;const token=beginOperation('report');if(!token)return;
  try{const blob=await request<Blob>(`/reports/${id}/export?format=${format}${historical?'&include_stale=true':''}`,{signal:token.controller.signal,responseType:'blob'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`evidencelab-${id.slice(0,8)}${historical?'-historical':''}.${format==='json'?'json':'md'}`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);setNotice(historical?'已导出历史报告快照；请留意报告的过期状态与当前实验差异。':'报告已下载。');}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function verifyClaim(event:FormEvent){
  event.preventDefault();if(!claim.trim()||!selected.length||busy)return;const submitted=claim.trim(),scope=[...selected],submittedEngine=verifyEngine,token=beginOperation('verify');if(!token)return;
  try{const data=await post<VerifyResult>('/verify',{claim:submitted,paper_ids:scope,engine:submittedEngine},{signal:token.controller.signal,timeoutMs:submittedEngine==='local'?30000:400000});setVerification({...data,claim:submitted,paper_ids:scope});}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function beginEdit(exp:Experiment){
  setManualCandidate(false);
  setError(null);try{const source=await getDetail(exp.paper_id,true);const latest=source.experiments.find(item=>item.id===exp.id);if(!latest){setError('此实验已不在当前实验库，不能从历史快照覆盖。请刷新文献后查看。');return;}const revision=source.experiment_revisions?.[exp.id];if(!revision){setError('当前后端未提供实验版本，已停止编辑以防覆盖其他修改。请刷新并确认前后端版本一致。');return;}setEditRevision(revision);setEditConflict(false);setEditSources(source.evidence);setEditFieldEvidence(Object.fromEntries(Object.entries(latest.field_evidence??{}).map(([field,ids])=>[field,[...ids]])));setEditSourceField('method');setEditSourceQuery('');setEditExperiment(latest);}catch(err){operationError(err);}
 }
 async function beginManualCandidate(){
  if(!detail||busy)return;setError(null);
  try{const source=await getDetail(detail.id,true);setEditSources(source.evidence);setEditFieldEvidence({});setManualQuotes({});setManualCandidate(true);setEditRevision('manual');setEditConflict(false);setEditSourceField('value');setEditSourceQuery('');setEditExperiment({id:'new-manual-candidate',paper_id:source.id,name:'',method:null,dataset:null,split:null,metric:null,value:null,unit:null,sample_size:null,conditions:{},evidence_ids:[],field_evidence:{},extraction_method:'manual',notes:[]});}catch(err){operationError(err);}
 }
 async function showExperimentHistory(exp:Experiment){
  if(busy)return;const token=beginOperation('history');if(!token)return;
  try{const [entries,source]=await Promise.all([request<ExperimentHistoryEntry[]>(`/experiments/${exp.id}/history`,{signal:token.controller.signal}),getDetail(exp.paper_id,true)]);const current=source.experiments.find(item=>item.id===exp.id);if(!current)throw new Error('当前实验已不可用。');setExperimentHistory({current,entries,sources:source.evidence,paper:source});}catch(err){operationError(err);}finally{finishOperation(token);}
 }
 async function saveExperiment(event:FormEvent<HTMLFormElement>){
  event.preventDefault();if(!editExperiment||busy||editConflict)return;if(!editRevision){setError('缺少实验版本，请重新载入后编辑。');return;}const form=new FormData(event.currentTarget),exp=editExperiment,keys=['name','task','method','dataset','split','metric','unit','sample_size'];const body:Record<string,unknown>={expected_revision:editRevision};keys.forEach(key=>body[key]=String(form.get(key)??'').trim()||null);const value=String(form.get('value')??'').trim();body.value=value?Number(value):null;
  if(value&&!Number.isFinite(body.value)){setError('结果数值必须是有限数。');return;}
  const conditions:Record<string,string>={};for(const line of String(form.get('conditions')??'').split('\n').filter(line=>line.trim())){const index=line.indexOf(':');if(index<1||!line.slice(index+1).trim()){setError('每项实验条件请使用“名称: 内容”格式，一行一项。');return;}const key=line.slice(0,index).trim();if(key in conditions){setError(`实验条件名称重复：${key}`);return;}conditions[key]=line.slice(index+1).trim();}
  body.conditions=conditions;body.field_evidence=editFieldEvidence;body.evidence_ids=[...new Set([...exp.evidence_ids,...Object.values(editFieldEvidence).flat()])];const token=beginOperation('save');if(!token)return;
  if(manualCandidate){
   try{const fields=Object.fromEntries(Object.entries(body).filter(([key])=>!['name','expected_revision','evidence_ids','field_evidence'].includes(key)));const evidence_quotes=Object.fromEntries(Object.entries(editFieldEvidence).map(([field,ids])=>[field,ids.map(id=>({id,quote:manualQuotes[field]?.[id]??editSources.find(item=>item.id===id)?.text??''}))]));const updated=await post<PaperDetail>(`/papers/${exp.paper_id}/manual-candidates`,{name:body.name,fields,evidence_quotes},{signal:token.controller.signal});detailCache.current[updated.id]=updated;setDetail(updated);setEditExperiment(null);await refresh();setNotice('已建立人工候选，尚未纳入实验库。请核查各字段原文后接受所选候选。');}catch(err){operationError(err);}finally{finishOperation(token);}return;
  }
  try{await request<Experiment>(`/experiments/${exp.id}`,{method:'PATCH',body:JSON.stringify(body),signal:token.controller.signal});const updated=await getDetail(exp.paper_id,true);setDetail(current=>current?.id===updated.id?updated:current);if(comparison&&!comparisonSnapshot)setComparison({...comparison,experiments:comparison.experiments.map(item=>item.id===exp.id?updated.experiments.find(record=>record.id===item.id)??item:item)});setComparisonStale(true);setEditExperiment(null);await refresh();setNotice('已保存人工修正和字段来源，请重新生成比较。人工来源关联仍需核查语义支持。');}catch(err){if(err instanceof ApiError&&err.status===409)setEditConflict(true);operationError(err);}finally{finishOperation(token);}
 }
 function dropFiles(event:DragEvent){event.preventDefault();setDragging(false);void uploadFiles(Array.from(event.dataTransfer.files));}
 function fieldEvidence(exp:Experiment,field:string){return exp.field_evidence[field]??[];}
 function resultScope(ids:string[]){return <details className="result-scope"><summary>本次结果的文献范围 · {ids.length} 篇</summary><ul>{ids.map(id=><li key={id}>{papers.find(p=>p.id===id)?.title??'该来源文献已不可用'}</li>)}</ul></details>;}
 function comparisonOrigin():EvidenceOrigin{return {label:`${comparisonSnapshot?'历史报告':'本次报告'} · ${comparison?formatDate(comparison.created_at):''} · 保存的原文摘录`,papers:comparison?.papers??[],historical:comparisonSnapshot};}
 function openComparisonEvidence(ids:string[],paperId?:string){const found=comparison?.evidence?.filter(item=>ids.includes(item.id)&&(!paperId||item.paper_id===paperId))??[];if(found.length){openEvidence(found[0],found,comparisonOrigin());if(found.length<ids.length)setNotice('报告只保留了部分关联摘录，请留意缺失来源。');return;}if(comparisonSnapshot){setError('这份历史报告未保存所请求的原文摘录，不能用当前资料补写历史依据。');return;}void openEvidenceIds(ids,paperId,comparison?.papers.map(p=>p.id));}
 function openFieldEvidence(exp:Experiment,field:string,sources?:Evidence[],origin?:EvidenceOrigin){const context={label:fieldNames[field]??field,quotes:exp.evidence_quotes?.[field]??[]};if(sources){const found=sources.filter(item=>fieldEvidence(exp,field).includes(item.id));if(found.length){evidenceRequest.current++;setActiveEvidence({item:found[0],list:found,fieldContext:context,origin});return;}}if(origin?.historical){setError('该历史字段的完整摘录未保留，无法定位；请核对快照中已保存的字段引文。');return;}return openEvidenceIds(fieldEvidence(exp,field),exp.paper_id,undefined,context);}
 function valueCell(exp:Experiment,field:keyof Experiment,sources?:Evidence[],origin?:EvidenceOrigin){const value=exp[field];return <button className="matrix-value" title={fieldEvidence(exp,field).length?'查看该字段原文证据':'此字段尚无直接来源关联'} disabled={!fieldEvidence(exp,field).length} onClick={()=>void openFieldEvidence(exp,field,sources,origin)}>{value===null||value===undefined||value===''?'未报告':String(value)}{fieldEvidence(exp,field).length>0&&<ArrowSquareOut size={11}/>}</button>;}
 function experimentCard(exp:Experiment,candidate?:ExtractionCandidate,historyContext?:{sources:Evidence[];origin:EvidenceOrigin}){const sources=historyContext?.sources??(candidate?[...new Map([...(detail?.evidence??[]),...(candidate.source_evidence??[])].map(item=>[item.id,item])).values()]:undefined);const origin=historyContext?.origin;return <article key={exp.id} className="experiment-card"><div className="row between"><h3>{exp.name}</h3>{!candidate&&!historyContext&&<div className="row"><button className="text-button small" disabled={!!busy} onClick={()=>void showExperimentHistory(exp)}><ArrowClockwise size={14}/>修改历史</button><button className="text-button small" disabled={!!busy} onClick={()=>void beginEdit(exp)}><PencilSimple size={14}/>人工修正</button></div>}</div><dl className="experiment-fields">{Object.entries(fieldNames).filter(([field])=>field!=='conditions').map(([field,label])=><div key={field}><dt>{label}</dt><dd>{valueCell(exp,field as keyof Experiment,sources,origin)}</dd></div>)}</dl>{Object.keys(exp.conditions??{}).length>0&&<div className="experiment-conditions">{Object.entries(exp.conditions).map(([key,value])=><button className="text-button small" key={key} disabled={!fieldEvidence(exp,'conditions').length} onClick={()=>void openFieldEvidence(exp,'conditions',sources,origin)}>{key}：{value}{fieldEvidence(exp,'conditions').length>0&&<ArrowSquareOut size={11}/>}</button>)}</div>}<WarningNotes warnings={exp.notes??[]}/><div className="row between"><div className="row experiment-source-tags"><Tag>{exp.extraction_method==='demo'?'演示记录':exp.extraction_method==='llm'?'模型提取':exp.extraction_method==='manual'?'人工编辑':'规则提取'}</Tag><Tag tone="amber">需人工核查实验归属</Tag>{!!exp.source_pages?.length&&<span className="micro muted">来源页 {exp.source_pages.join('、')}</span>}</div><button className="text-button small" disabled={!exp.evidence_ids.length} onClick={()=>{const found=sources?.filter(item=>exp.evidence_ids.includes(item.id));if(found?.length)openEvidence(found[0],found,origin);else if(origin?.historical)setError('历史记录中没有保留这些原文摘录。');else void openEvidenceIds(exp.evidence_ids,exp.paper_id);}}><Link size={14}/>{exp.evidence_ids.length} 条原文证据<ArrowRight size={13}/></button></div></article>;}
 const corpusChanged=comparison&&!comparison.papers.every(p=>selected.includes(p.id))||comparison&&selected.length!==comparison.papers.length;

 return <div className="app-shell">
  <a className="skip-link" href="#workspace-content">跳到工作区</a>
  {mobileNav&&<button className="nav-scrim" aria-label="关闭导航" onClick={()=>setMobileNav(false)}/>}
  <aside className={`sidebar ${mobileNav?'is-open':''}`}>
   <button className="brand" onClick={()=>changePage('library')} aria-label="EvidenceLab 首页"><span className="brand-mark"><BookOpen size={24} weight="bold"/></span><span>Evidence<span className="brand-light">Lab</span><small>文献证据工作台</small></span></button>
   <div className="workspace-picker"><span className="workspace-icon"><Flask size={18}/></span><div><strong>我的研究空间</strong><small>本地工作区</small></div><LockKey size={14}/></div>
   <div className="nav-label">研究工具</div>
   <nav aria-label="主要导航">{nav.map(({id,label,icon:Icon})=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>changePage(id)}><Icon size={21} weight={page===id?'duotone':'regular'}/><span>{label}</span>{id==='library'&&papers.length>0&&<span className="nav-count">{papers.length}</span>}{page===id&&<span className="nav-active-indicator"/>}</button>)}</nav>
   <div className="sidebar-note"><ShieldCheck size={21}/><strong>让每个结论有据可查</strong><p>从原文出发，保留证据，审慎比较。</p></div>
   <div className="sidebar-bottom"><span className={`status-dot ${health?'online':''}`}/><div><strong>{health?'本地服务已连接':'等待连接本地服务'}</strong><small>{health?.providers.llm_status?providerStatusNames[health.providers.llm_status]:health?.providers.llm_configured?'模型已配置 · 连接未验证':'本地检索模式'}</small></div><button className="icon-button" onClick={()=>void refresh()} aria-label="刷新服务状态"><ArrowClockwise size={16}/></button></div>
  </aside>
  <div className="workspace-main">
   <header className="topbar"><div className="row breadcrumb"><button className="icon-button mobile-toggle" aria-label="打开导航" onClick={()=>setMobileNav(true)}><List size={21}/></button><span>研究空间</span><CaretRight size={13}/><strong>{currentNav.label}</strong></div><div className="topbar-right"><span className="local-label"><LockKey size={13}/>本地工作区</span><span className="avatar" aria-label="研究员">研</span></div></header>
    <main className="main-content" id="workspace-content">
    <div className="page-heading"><div><div className="page-kicker">RESEARCH WORKSPACE</div><h1>{currentNav.label}<span className="heading-period">.</span></h1><p>{{library:'整理研究资料，从文献中建立可追溯的证据。',qa:'围绕选定文献提问，沿着引用回到原文。',compare:'对齐实验条件，理解结果背后的差异。',verify:'检查研究结论与原文证据的对应关系。',settings:'查看运行环境与已启用的分析能力。'}[page]}</p></div>{page==='library'?<button className="button primary" disabled={!!busy} onClick={()=>fileInput.current?.click()}>{busy==='upload'?<Spinner/>:<Plus size={18}/>}导入文献</button>:page==='compare'?<button className="button primary" disabled={selected.length<2||!!busy} onClick={()=>void runComparison()}>{busy==='compare'?<Spinner/>:<GitDiff size={18}/>}生成对比分析</button>:null}</div>
    {error&&<div className="alert error" role="alert"><WarningCircle size={20}/><span>{error}</span>{page==='qa'&&engine!=='local'&&<button className="text-button" onClick={()=>{setEngine('local');setError(null);setNotice('已切换本地证据检索，保留问题，可重新发送。');}}>切换本地检索</button>}{page==='verify'&&verifyEngine!=='local'&&<button className="text-button" onClick={()=>{setVerifyEngine('local');setError(null);setNotice('已切换本地保守核验，保留结论，可重新提交。');}}>切换保守核验</button>}<button className="icon-button" aria-label="关闭错误提示"  onClick={()=>setError(null)}><X size={17}/></button></div>}
    {notice&&<div className="alert success" role="status"><CheckCircle size={19}/><span>{notice}</span><button className="icon-button" aria-label="关闭提示" onClick={()=>setNotice(null)}><X size={17}/></button></div>}
    <input className="visually-hidden" ref={fileInput} type="file" accept=".pdf,.txt,.md" multiple aria-label="上传文献文件" onChange={e=>void uploadFiles(Array.from(e.target.files??[]))}/>
     {busy&&<div className="operation-status" role="status" aria-live="polite"><Spinner/><div><strong>正在{operationNames[busy]??'处理任务'}</strong><span>已等待 {elapsed} 秒{busy==='qa'&&engine!=='local'||busy==='verify'&&verifyEngine!=='local'||busy==='extract'?' · 模型任务可能需要更长时间':''}</span></div>{['qa','compare','verify','extract','report'].includes(busy)&&<button className="button secondary small" onClick={cancelOperation}><X size={14}/>停止等待</button>}</div>}
     {page!=='library'&&page!=='settings'&&<section className="scope-panel" aria-label="文献研究范围"><div className="corpus-bar"><div className="row"><Stack size={18}/><span>研究范围</span><strong>{selected.length} 篇文献</strong>{selectedPapers.some(p=>p.is_demo)&&<Tag tone="amber">含合成演示材料</Tag>}</div><button className="text-button" onClick={()=>changePage('library')}>管理文献<ArrowRight size={14}/></button></div><details open={scopeOpen} onToggle={event=>setScopeOpen(event.currentTarget.open)}><summary>{selected.length?'调整本次分析文献':'先选择文献，再开始分析'}<span>最多 30 篇 · 选择会在当前浏览器保留</span></summary><div className="scope-options">{readyPapers.map(p=><label key={p.id}><input type="checkbox" aria-label={`研究范围：${p.title}`} checked={selected.includes(p.id)} disabled={!selected.includes(p.id)&&selected.length>=30} onChange={()=>togglePaper(p.id)}/><span>{p.title}<small>{p.experiment_count} 组实验 · {p.evidence_count} 条证据{p.is_demo?' · 合成演示材料':''}</small></span></label>)}</div>{!readyPapers.length&&<p className="scope-help">暂无可用文献。请先导入 PDF、TXT 或 Markdown。</p>}</details>{page==='compare'&&selected.length<2&&<p className="scope-help">比较需要至少两篇文献；每篇至少一项实验才能进行跨论文条件分析。</p>}</section>}

    {page==='library'&&<>
     <section className="library-intro"><div className={`upload-zone ${dragging?'dragging':''} ${busy==='upload'?'uploading':''}`} onDragOver={event=>{event.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={dropFiles}><div className="upload-symbol">{busy==='upload'?<CircleNotch className="spin" size={27}/>:<UploadSimple size={27}/>}</div><div><h2>{busy==='upload'?'正在解析与建立证据索引':'把研究资料带到这里'}</h2><p>{busy==='upload'?'保留原文页码，提取实验信息，请稍候。':'拖放论文文件，或选择文件开始建立文献库'}</p><div className="upload-formats"><span>PDF</span><span>TXT</span><span>Markdown</span><span className="muted">支持多文件上传</span></div></div><button className="button secondary" disabled={!!busy} onClick={()=>fileInput.current?.click()}>选择文件<ArrowRight size={15}/></button></div><div className="research-overview"><div className="section-label"><Database size={16}/>文献库概览</div><div className="overview-numbers"><div><strong>{papers.length.toString().padStart(2,'0')}</strong><span>篇文献</span></div><div><strong>{totalEvidence.toString().padStart(2,'0')}</strong><span>条原文证据</span></div><div><strong>{totalExperiments.toString().padStart(2,'0')}</strong><span>组实验</span></div></div><div className="overview-foot"><span className="status-dot online"/>数据来自当前文献库</div></div></section>
     <section className="library-section"><div className="library-toolbar"><div className="segmented-tabs"><button className={!selectedOnly?'active':''} onClick={()=>setSelectedOnly(false)}>全部文献<span>{papers.length}</span></button><button className={selectedOnly?'active':''} onClick={()=>setSelectedOnly(true)}>已选文献<span>{selected.length}</span></button></div><div className="row toolbar-controls"><label className="search-field"><MagnifyingGlass size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索标题、作者或文件名" aria-label="搜索文献"/>{search&&<button className="icon-button" aria-label="清除搜索" onClick={()=>setSearch('')}><X size={13}/></button>}</label><div className="view-toggle"><button aria-label="卡片视图" aria-pressed={!listView} className={!listView?'active':''} onClick={()=>setListView(false)}><SquaresFour size={18}/></button><button aria-label="列表视图" aria-pressed={listView} className={listView?'active':''} onClick={()=>setListView(true)}><ListBullets size={18}/></button></div></div></div>
      <div className="selection-toolbar"><label className="checkbox-label"><input type="checkbox" checked={allSelected} disabled={!readyPapers.length} onChange={()=>setSelected(allSelected?[]:readyPapers.slice(0,30).map(p=>p.id))}/>{readyPapers.length>30?'选择前 30 篇可用文献':'全选可用文献'}</label><span>{selected.length?`已选择 ${selected.length} 篇，作为问答与分析范围`:'勾选文献，开始有范围的研究'}</span>{selected.length>0&&<div className="row selection-actions"><button className="text-button" onClick={()=>changePage('qa')}>问答<ArrowRight size={13}/></button><button className="text-button" disabled={selected.length<2} onClick={()=>changePage('compare')}>对比分析<ArrowRight size={13}/></button></div>}</div>
      {initialLoading?<div className="loading-state"><Spinner/><span>正在读取文献库…</span></div>:filteredPapers.length?<div className={`paper-grid ${listView?'paper-list':''}`}>{filteredPapers.map((paper,index)=><article className={`paper-card ${selected.includes(paper.id)?'selected':''}`} key={paper.id}><div className="paper-top"><label className="paper-checkbox"><input type="checkbox" aria-label={`选择 ${paper.title}`} disabled={paper.status!=='ready'||!selected.includes(paper.id)&&selected.length>=30} checked={selected.includes(paper.id)} onChange={()=>togglePaper(paper.id)}/></label><span className="paper-index">{String(index+1).padStart(2,'0')}</span><div className="paper-status"><Tag tone={paper.status==='ready'?'green':paper.status==='failed'?'red':'amber'}>{paper.status==='ready'?<CheckCircle size={12}/>:paper.status==='failed'?<WarningCircle size={12}/>:<CircleNotch className="spin" size={12}/>} {paper.status==='ready'?'已就绪':paper.status==='failed'?'解析失败':'处理中'}</Tag></div><button className="icon-button delete-button" aria-label={`删除 ${paper.title}`} disabled={!!busy} onClick={()=>{setError(null);setDeletePaper(paper);}}><Trash size={16}/></button></div><button className="paper-body" onClick={()=>void showDetail(paper)} disabled={detailLoading===paper.id}><div className="paper-format">{/\.pdf$/i.test(paper.filename)?<FilePdf size={23}/>:<FileText size={23}/>}<span>{paper.is_demo?'SYNTHETIC DEMO':paper.filename.split('.').pop()?.toUpperCase()??'DOCUMENT'}</span>{paper.is_demo&&<Tag tone="amber">合成演示</Tag>}</div><h3>{paper.title}</h3><p className="paper-authors">{paper.authors.length?paper.authors.join(' · '):'作者未识别'}{paper.year?` · ${paper.year}`:''}</p><p className="paper-filename" title={paper.filename}>{paper.filename}</p></button><div className="paper-metrics"><span><Link size={14}/><strong>{paper.evidence_count}</strong>条证据</span><span><TestTube size={14}/><strong>{paper.experiment_count}</strong>组实验</span><span>{paper.page_count} 页</span></div>{paper.error&&<p className="paper-error">{paper.error}</p>}<div className="paper-footer"><span>{formatDate(paper.created_at)} 导入</span><button className="text-button" onClick={()=>void showDetail(paper)} disabled={detailLoading===paper.id}>{detailLoading===paper.id?<Spinner/>:'查看文献'}<ArrowRight size={13}/></button></div></article>)}</div>:papers.length?<Empty icon={FileMagnifyingGlass} title="没有找到匹配的文献"><p>尝试其他关键词，或切换到全部文献。</p></Empty>:<div className="library-empty"><div className="empty-document"><FileText size={37}/><span/><span/><span/></div><div><h3>你的第一条证据，从一篇文献开始</h3><p>导入论文后，正文、实验与原文位置将在这里连接起来。</p><button className="text-button" disabled={!!busy} onClick={()=>fileInput.current?.click()}>导入第一篇文献<ArrowRight size={15}/></button></div></div>}
     </section>
     <section className="library-bottom"><div className="method-note"><span className="method-icon"><Scales size={22}/></span><div><strong>先对齐条件，再比较结果</strong><p>保留数据集、实验设置和指标口径，让差异分析有清晰的边界。</p></div></div><button className="demo-entry" disabled={!!busy} onClick={()=>{setError(null);setShowDemo(true);}}><span className="demo-icon"><Flask size={20}/></span><span><strong>先体验完整流程</strong><small>载入 3 篇明确标注的合成演示文献</small></span>{busy==='demo'?<Spinner/>:<ArrowRight size={18}/>}</button></section>
    </>}

    {page==='qa'&&<div className="qa-layout"><aside className="qa-sidebar"><div className="row between"><h3>问答记录</h3><button className="icon-button" aria-label="新建问答" onClick={()=>{setActiveQuestion(null);setQuestion('');}}><Plus size={18}/></button></div>{!conversations.length?<p className="history-empty">你的问题与引用来源<br/>会保留在本次会话中。</p>:<div className="history-list">{conversations.map(item=><button className={activeQuestion===item.id?'active':''} key={item.id} onClick={()=>setActiveQuestion(item.id)}><ChatCircleText size={16}/><span>{item.question}</span></button>)}</div>}<div className="qa-scope"><h4>当前研究范围</h4>{selectedPapers.length?selectedPapers.map(p=><div key={p.id}><FileText size={14}/><span>{p.title}</span></div>):<p>还未选择文献</p>}</div></aside><section className="qa-main">{activeConversation?<div className="answer-content"><div className="question-bubble"><span className="avatar">研</span><h2>{activeConversation.question}</h2></div><div className="answer-meta"><span className="answer-symbol"><BookOpen size={18}/></span><strong>EvidenceLab</strong><Tag>{engineNames[activeConversation.result.mode]??activeConversation.result.mode}</Tag><Tag>{activeConversation.paper_ids.length} 篇 · 本次回答范围</Tag><Tag tone={!activeConversation.result.withheld_assertions?.length&&activeConversation.result.verdict==='evidence_found'?'green':'amber'}>{activeConversation.result.withheld_assertions?.length?'回答不完整':activeConversation.result.verdict==='evidence_found'?(activeConversation.result.mode==='local'?'已检索到候选原文':'已找到原文证据'):activeConversation.result.verdict==='unverified'?'尚未完成证据核验':'证据不足'}</Tag></div>{resultScope(activeConversation.paper_ids)}{!sameScope(activeConversation.paper_ids,selected)&&<p className="scope-result-note">此回答基于提交时的文献范围；当前选择已变化，新问题将使用当前范围。</p>}{!!activeConversation.result.withheld_assertions?.length&&<div className="alert warning"><WarningCircle size={18}/><div><strong>回答不完整 · {activeConversation.result.withheld_assertions.length} 项模型断言已暂缓</strong><p>对象、指标或评估协议的来源检查未通过；暂缓内容未作为事实展示。下方只保留通过当前检查的回答，仍需人工核对。</p><WarningNotes warnings={[...new Set(activeConversation.result.withheld_assertions.flatMap(item=>item.reasons))]}/></div></div>}<div className="answer-text">{qaDisplayAnswer(activeConversation.result)}</div>
     {!!activeConversation.result.assertion_evidence?.length&&<details className="assertion-provenance"><summary>逐句核对原文 · {activeConversation.result.assertion_evidence.length} 项回答</summary>{activeConversation.result.assertion_evidence.map((assertion,index)=><article key={index}><h4>{assertion.text}</h4><EvidenceCards citations={activeConversation.result.citations.filter(item=>assertion.citation_quotes.some(quote=>quote.id===item.id))} papers={papers} quotes={assertion.citation_quotes} onOpen={openEvidence} onOpenQuote={openCitedEvidence}/></article>)}</details>}
     <WarningNotes warnings={activeConversation.result.warnings}/>{activeConversation.result.verification&&<ModelVerification title={activeConversation.result.withheld_assertions?.length?'已展示回答的二次模型核验':'回答的二次模型核验'} result={activeConversation.result.verification} citations={activeConversation.result.verification.citations??activeConversation.result.citations} papers={papers} onOpen={openEvidence} onOpenQuote={openCitedEvidence}/>}{activeConversation.result.citations.length>0&&<><div className="subsection-heading"><h3>关联原文</h3><span>{activeConversation.result.citations.length} 条引用 · {activeConversation.result.withheld_assertions?.length?'含暂缓内容来源，需人工核查':'点击核查'}</span></div><EvidenceCards citations={activeConversation.result.citations} papers={papers} quotes={activeConversation.result.citation_quotes} onOpen={openEvidence} onOpenQuote={openCitedEvidence}/></>}<Traces traces={activeConversation.result.traces} onEvidence={ids=>void openEvidenceIds(ids,undefined,activeConversation.paper_ids)}/></div>:<div className="qa-welcome"><span className="welcome-mark"><ChatCircleText size={35}/></span><span className="section-label">从一个好问题开始</span><h2>和文献对话，让证据说话。</h2><p>选择研究范围，提出问题。每条回答保留引用，便于回到原文核查。</p><div className="question-suggestions">{['各篇文献使用了哪些数据集和评价指标？','这些研究的实验设置有哪些差异？','哪些原文证据支持论文报告的结果？'].map(text=><button key={text} onClick={()=>setQuestion(text)}><span>{text}</span><ArrowUp size={15}/></button>)}</div></div>}<form className="question-composer" onSubmit={askQuestion}><textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder={selected.length?'向选定文献提问，例如：这些实验在什么条件下可以比较？':'请先在文献库勾选研究资料'} aria-label="研究问题" rows={3} maxLength={4000} disabled={busy==='qa'}/><div className="composer-footer"><label className="engine-picker"><Robot size={16}/><select aria-label="问答引擎" disabled={busy==='qa'} value={engine} onChange={e=>setEngine(e.target.value as Engine)}><ResearchEngineOptions purpose="qa" providers={health?.providers}/></select></label><span className="composer-hint">{selected.length} 篇文献 · 引用可追溯</span><button className="send-button" type="submit" aria-label="发送问题" disabled={!question.trim()||!selected.length||!!busy}>{busy==='qa'?<Spinner/>:<ArrowUp size={19} weight="bold"/>}</button></div></form><p className="composer-disclaimer">{engine==='local'?'本地模式仅检索候选原文，不执行模型综合推理。':'模型已配置不等于调用可用；本次请求会调用模型，结果仍需核对原文。'}</p></section></div>}

    {page==='compare'&&<><div className="analysis-guidance"><Scales size={21}/><p>以<strong>实验</strong>为比较单位，先检查数据集、划分、指标与条件，再分析结果差异。</p></div>{comparison?<>
     {comparisonSnapshot&&<div className="alert warning historical-banner"><Info size={19}/><span><strong>正在查看只读报告快照 · {formatDate(comparison.created_at)}</strong><br/>以下实验、判断和摘录均来自保存时的版本，不代表当前研究状态。{comparison.stale_reason??(comparisonStale?'相关实验已有更新，请重新生成以获得当前判断。':'')}</span></div>}{!comparisonSnapshot&&(comparisonStale||corpusChanged)&&<div className="alert warning"><WarningCircle size={19}/><span>{corpusChanged?'当前选择与这份报告的文献范围不同。':'实验字段已更新，原有比较判断需要重新计算。'}请点击“生成对比分析”更新报告。</span></div>}
     <section className="comparison-coverage"><h3>各文献实验覆盖</h3><p>矩阵只包含已保存实验。缺少实验或实验归属不明时，先检查原文并审阅提取候选。</p><div>{comparison.papers.map(p=>{const count=comparison.experiments.filter(exp=>exp.paper_id===p.id).length;return <button key={p.id} disabled={!papers.some(current=>current.id===p.id)} title={!papers.some(current=>current.id===p.id)?'当前文献已不可用；快照摘录仍可查看':'打开当前文献详情'} onClick={()=>void showDetail(p)}><span>{p.title}</span><Tag tone={count?'green':'amber'}>{count} 组实验</Tag>{!papers.some(current=>current.id===p.id)&&<Tag tone="amber">原文不可用</Tag>}<ArrowSquareOut size={14}/></button>;})}</div></section><WarningNotes warnings={comparison.warnings??[]}/><section className="panel comparison-panel"><div className="panel-heading"><div><h2>{comparisonSnapshot?'保存的实验对比矩阵':'实验对比矩阵'}</h2><p>{comparison.papers.length} 篇文献 · {comparison.experiments.length} 组实验 · 点击字段查看证据</p></div><div className="row export-actions"><button className="button secondary small" disabled={comparisonStale||!!corpusChanged||!!busy} onClick={()=>void downloadReport(comparison.id,'markdown')}><DownloadSimple size={15}/>报告</button><button className="button secondary small" disabled={comparisonStale||!!corpusChanged||!!busy} onClick={()=>void downloadReport(comparison.id,'json')}><BracketsCurly size={15}/>JSON</button></div></div>{comparison.experiments.length?<div className="table-scroll"><table className="comparison-table"><thead><tr><th>文献 / 实验</th><th>研究任务</th><th>方法</th><th>数据集</th><th>数据划分</th><th>样本量</th><th>评价指标</th><th>报告结果</th><th>证据</th><th/></tr></thead><tbody>{comparison.experiments.map(exp=><tr key={exp.id}><td><strong>{comparison.papers.find(p=>p.id===exp.paper_id)?.title??'来源文献'}</strong><span>{exp.name}</span>{exp.review_required!==false&&<Tag tone="amber">需人工复核</Tag>}{exp.extraction_method==='demo'&&<Tag tone="amber">合成演示</Tag>}</td><td>{valueCell(exp,'task',comparison.evidence,comparisonOrigin())}</td><td>{valueCell(exp,'method',comparison.evidence,comparisonOrigin())}</td><td>{valueCell(exp,'dataset',comparison.evidence,comparisonOrigin())}</td><td>{valueCell(exp,'split',comparison.evidence,comparisonOrigin())}</td><td>{valueCell(exp,'sample_size',comparison.evidence,comparisonOrigin())}</td><td>{valueCell(exp,'metric',comparison.evidence,comparisonOrigin())}</td><td><button className="metric-result" disabled={!fieldEvidence(exp,'value').length} onClick={()=>void openFieldEvidence(exp,'value',comparison.evidence,comparisonOrigin())}>{exp.value??'未报告'}<span>{exp.unit}</span>{fieldEvidence(exp,'value').length>0&&<ArrowSquareOut size={12}/>}</button></td><td><button className="evidence-count" disabled={!exp.evidence_ids.length} onClick={()=>void openComparisonEvidence(exp.evidence_ids,exp.paper_id)}><Link size={13}/>{exp.evidence_ids.length}</button></td><td><button className="icon-button" disabled={comparisonSnapshot||!!busy} title={comparisonSnapshot?'历史快照只读，请打开当前文献编辑':undefined} aria-label={`修正 ${exp.name}`} onClick={()=>{setError(null);void beginEdit(exp);}}><PencilSimple size={15}/></button></td></tr>)}</tbody></table></div>:<Empty icon={TestTube} title="尚未提取到实验"><p>打开文献详情检查原文，或配置模型后尝试增强提取。</p></Empty>}</section>
     <div className="subsection-heading large"><h2>条件对齐与差异判断</h2><span>{comparison.comparisons.length} 组比较</span></div>{!comparisonSnapshot&&(comparisonStale||corpusChanged)?<Empty icon={ArrowClockwise} title="等待重新生成分析"><p>点击“生成对比分析”后显示与当前实验和文献范围一致的判断。原报告仍作为历史快照保存。</p></Empty>:comparison.comparisons.length?<div className="comparison-pairs">{comparison.comparisons.map(pair=>{const left=comparison.experiments.find(exp=>exp.id===pair.left_id);const right=comparison.experiments.find(exp=>exp.id===pair.right_id);return <article className="pair-card" key={pair.id}><div className="row between"><Tag tone={pair.comparability==='direct'?'green':pair.comparability==='incomparable'?'red':'amber'}>{comparabilityNames[pair.comparability]}</Tag><Tag tone={pair.verdict==='potential_conflict'?'red':'neutral'}>{verdictNames[pair.verdict]}</Tag></div><h3>{left?.method??left?.name??'实验 A'}<span>与</span>{right?.method??right?.name??'实验 B'}</h3><div className="pair-paper-names"><span>{comparison.papers.find(p=>p.id===left?.paper_id)?.title}</span><span>{comparison.papers.find(p=>p.id===right?.paper_id)?.title}</span></div><div className="pair-reasons">{pair.reasons.map((reason,i)=><p key={i}><Scales size={14}/>{reason}</p>)}{pair.differences.map((difference,i)=><p key={`d-${i}`}><GitDiff size={14}/>{difference}</p>)}</div>{pair.alignment&&<details className="alignment-details"><summary>查看逐字段条件对齐</summary><div>{Object.entries(pair.alignment).map(([field,aligned])=><div className="alignment-row" key={field}><strong>{fieldNames[field]??field}</strong><span>{aligned.left===null||aligned.left===undefined?'未报告':String(aligned.left)} / {aligned.right===null||aligned.right===undefined?'未报告':String(aligned.right)}</span><small>{aligned.status==='same'?'一致':aligned.status==='different'?'不一致':'信息不足'}</small></div>)}</div></details>}{!!pair.conflict_evidence?.length&&<div className="conflict-quotes"><strong>相反原文论断 · 仍需人工核验</strong>{pair.conflict_evidence.map((ref,index)=><blockquote key={index}><p>{ref.quote}</p><button className="text-button small" onClick={()=>void openComparisonEvidence([ref.id],ref.paper_id)}>查看来源<ArrowSquareOut size={12}/></button></blockquote>)}</div>}<div className="pair-footer">{pair.delta!==null?<span>报告数值差值 <strong>{pair.delta}</strong><small>差值本身不代表优劣或冲突</small></span>:<span className="muted">保留条件限制，避免直接排名</span>}<button className="text-button small" disabled={!pair.evidence_ids.length} onClick={()=>void openComparisonEvidence(pair.evidence_ids)}>核查依据<ArrowRight size={13}/></button></div></article>;})}</div>:<Empty icon={Scales} title="没有可成对分析的实验"><p>本次请求已完成，但所选文献尚不足两篇包含实验。请在上方“各文献实验覆盖”打开缺少实验的论文，生成并审阅候选后重新比较。</p></Empty>}<Traces traces={comparison.traces} onEvidence={ids=>void openComparisonEvidence(ids)}/><p className="analysis-footnote"><Info size={14}/>规则分析仅依据已提取字段。潜在冲突需要结合完整论文及领域知识人工确认。</p>
    </>:<section className="panel analysis-empty"><div className="analysis-illustration"><span><FileText size={31}/></span><Scales size={30}/><span><FileText size={31}/></span></div><h2>把结果放回实验条件里</h2><p>选择至少两篇文献，生成可追溯的实验矩阵，<br/>检查条件是否一致，再理解结果为什么不同。</p><div className="workflow-mini"><span><TestTube size={16}/>实验提取</span><ArrowRight size={14}/><span><Scales size={16}/>条件对齐</span><ArrowRight size={14}/><span><ShieldCheck size={16}/>证据核验</span></div><button className="button primary" disabled={selected.length<2||!!busy} onClick={()=>void runComparison()}>{busy==='compare'?<Spinner/>:<GitDiff size={17}/>}生成第一份对比</button>{selected.length<2&&<small className="muted">当前选择 {selected.length} 篇，请在上方调整研究范围</small>}</section>}</>}

    {page==='compare'&&<details className="report-history"><summary><FileText size={17}/>已保存报告<span>{reports.length} 份</span></summary>{reportError?<p className="report-history-error">报告列表暂时无法读取：{reportError}<button className="text-button" onClick={()=>void refresh()}>重试</button></p>:reports.length?<div>{reports.map(report=><article key={report.id}><div><strong>{report.papers.map(p=>p.title).join(' / ')||'历史文献范围'}</strong><p>{formatDate(report.created_at)} · {report.experiment_count} 组实验 · {report.comparison_count} 组比较{report.stale?' · 已过期，保留历史快照':''}</p></div><button className="button secondary small" disabled={!!busy} onClick={()=>void loadReport(report.id)}>打开快照</button>{report.stale&&<button className="text-button small" disabled={!!busy} onClick={()=>void downloadReport(report.id,'markdown',true)}>导出历史快照</button>}</article>)}</div>:<p>尚无保存报告。生成比较后自动保存，之后可在此恢复。</p>}</details>}

    {page==='verify'&&<div className="verify-layout"><section className="panel verify-form-panel"><div className="panel-heading"><div><h2>提交待核验结论</h2><p>尽量包含研究对象、实验条件、指标和数值。</p></div><SealCheck size={25}/></div><form onSubmit={verifyClaim}><label className="field-label" htmlFor="claim">研究结论</label><textarea id="claim" rows={7} placeholder="输入你希望核验的具体结论。例如：方法 A 在同一测试集上的准确率高于方法 B。" value={claim} onChange={e=>setClaim(e.target.value)} maxLength={4000}/><label className="verification-engine field-label">核验方式<select aria-label="核验方式" value={verifyEngine} onChange={e=>setVerifyEngine(e.target.value as VerifyEngine)} disabled={busy==='verify'}><ResearchEngineOptions purpose="verify" providers={health?.providers}/></select></label><div className="row between verify-form-footer"><span className="micro muted">{claim.length} / 4000</span><button className="button primary" disabled={!claim.trim()||!selected.length||!!busy}>{busy==='verify'?<Spinner/>:<SealCheck size={17}/>}核验结论</button></div></form><div className="verification-boundary"><LockKey size={17}/><div><strong>核验范围清晰，判断才有意义</strong><p>{verifyEngine==='llm'?'将调用模型检查原文支持关系。连接或模型故障会明确报错，可切换本地核验；判断仍需人工复核。':'仅检索候选证据并保守返回“证据不足”，不做语义真实性判断；未找到证据不代表结论错误。'}</p></div></div></section><aside className="verification-guide"><span className="section-label">模型核验结果如何理解</span>{[{label:'模型判断 · 原文支持',text:'模型认为原文支持命题，仍须核对对象、数值和实验条件，不能视为系统认证。',tone:'green'},{label:'模型判断 · 部分支持',text:'模型认为部分内容有依据，其余内容或限定条件仍不明确，需人工复核。',tone:'amber'},{label:'证据不足',text:'当前来源或检查结果不足以支持判断；不能因此认定命题为假。',tone:'neutral'},{label:'模型判断 · 与原文不符',text:'模型认为原文与命题存在矛盾，也可能发生实验归属错误，必须回到原文复核。',tone:'red'}].map(item=><div className="guide-item" key={item.label}><span className={`guide-indicator ${item.tone}`}/><div><strong>{item.label}</strong><p>{item.text}</p></div></div>)}<p className="guide-disclaimer">核验衡量结论与选定文献的关系，科研真实性仍需独立验证。</p></aside>{verification&&<section className="panel verification-result"><div className="panel-heading"><div className="row model-verdict-heading"><ShieldCheck size={23}/><h2>核验结果</h2><Tag tone={verification.verdict==='supported'?'green':verification.verdict==='contradicted'?'red':'amber'}>{verification.mode==='local'?verifyNames[verification.verdict]:modelVerifyNames[verification.verdict]}</Tag></div><span className="micro muted">{verification.mode==='llm'?'模型语义核验':verification.mode==='local'?'本地保守核验':engineNames[verification.mode]??verification.mode}</span></div>{resultScope(verification.paper_ids)}{!sameScope(verification.paper_ids,selected)&&<p className="scope-result-note">本结果使用提交时的 {verification.paper_ids.length} 篇文献；当前研究范围已变化，请重新核验。</p>}<blockquote>{verification.claim}</blockquote><ModelVerification title={verification.mode==='local'?'本地保守核验':'逐项模型核验'} local={verification.mode==='local'} result={verification} citations={verification.citations} papers={papers} onOpen={openEvidence} onOpenQuote={openCitedEvidence}/><WarningNotes warnings={verification.warnings}/>{verification.citations.length>0&&<><div className="subsection-heading"><h3>关联原文</h3><span>{verification.citations.length} 条候选证据</span></div><EvidenceCards citations={verification.citations} papers={papers} quotes={verification.citation_quotes} onOpen={openEvidence} onOpenQuote={openCitedEvidence}/></>}<Traces traces={verification.traces} onEvidence={ids=>void openEvidenceIds(ids,undefined,verification.paper_ids)}/></section>}</div>}

    {page==='settings'&&<div className="settings-layout"><section className="panel"><div className="panel-heading"><div><h2>运行能力与实际状态</h2><p>配置状态与最近调用结果分别展示，刷新状态不会发起付费请求。</p></div><button className="button secondary small" onClick={()=>void refresh()}><ArrowClockwise size={15}/>刷新状态</button></div><div className="capability-list">{[
     {icon:Database,name:'本地证据检索',description:'本地解析和候选原文检索，不执行模型综合推理',label:health?'本地服务已连接':'服务未连接',available:!!health},
     {icon:Robot,name:'聊天模型',description:'问答、候选实验提取与语义核验；需明确选择后调用',label:health?providerStatusNames[health.providers.llm_status??(health.providers.llm_configured?'untested':'unconfigured')]:'状态未知',available:health?.providers.llm_status==='available'},
     {icon:GitDiff,name:'LangGraph 协作流程',description:'编排实验整理、条件对齐、差异分析与来源检查规则',label:health?.providers.langgraph_available?'组件已安装':health?'组件未安装':'状态未知',available:!!health?.providers.langgraph_available},
    ].map(({icon:Icon,name,description,label,available})=><div className="capability-item" key={name}><span className="capability-icon"><Icon size={22}/></span><div><strong>{name}</strong><p>{description}</p></div><Tag tone={available?'green':'neutral'}>{label}</Tag></div>)}</div></section>
    <section className="panel environment-panel"><div className="panel-heading"><div><h2>模型连接说明</h2><p>凭据仅在后端保存</p></div><LockKey size={22}/></div><div className="environment-content"><p>后端读取项目环境配置。聊天模型可能发生连接、鉴权、模型名称或格式兼容错误。实际请求失败时，页面保留输入并显示原因，可以切换本地模式。</p><p>本地检索和规则比较不调用模型；模型增强提取、问答和语义核验会调用配置的服务，可能产生费用。</p><p className="micro muted"><ShieldCheck size={15}/>“已配置”仅说明字段齐全；“最近调用成功”仅描述已发生请求，不保证后续可用。</p></div></section>
    <section className="panel runtime-panel"><div className="panel-heading"><div><h2>安全运行配置</h2><p>仅显示后端公开的非敏感字段</p></div><BracketsCurly size={22}/></div><pre>{settings?JSON.stringify(settings,null,2):'无法读取运行配置，请确认服务连接。'}</pre></section></div>}
    <footer className="main-footer"><span>EvidenceLab</span><a href="https://github.com/0401chen/EvidenceLab" target="_blank" rel="noreferrer">项目源码</a><a href="https://github.com/0401chen/EvidenceLab/blob/main/LICENSE" target="_blank" rel="noreferrer">AGPL-3.0-only</a><a href="https://github.com/0401chen/EvidenceLab/blob/main/THIRD_PARTY_NOTICES.md" target="_blank" rel="noreferrer">第三方声明</a><span className="footer-right"><ShieldCheck size={13}/>可追溯 · 可核查</span></footer>
   </main>
  </div>

  {showDemo&&<Modal error={error} title="载入合成演示文献" onClose={()=>setShowDemo(false)} className="confirm-modal"><span className="confirm-icon"><Flask size={28}/></span><p>将向文献库添加 3 篇人工构造的示例文献，用于体验条件对齐、实验比较和证据追溯。</p><div className="alert warning"><Info size={18}/><span>这些材料不是真实论文，包含的作者、方法与数值仅用于演示，不能作为科研依据。</span></div><div className="modal-actions"><button className="button secondary" onClick={()=>setShowDemo(false)}>取消</button><button className="button primary" onClick={()=>void seedDemo()}>我已了解，载入演示</button></div></Modal>}
  {deletePaper&&<Modal error={error} title="删除文献" onClose={()=>{if(busy!=='delete')setDeletePaper(null);}} className="confirm-modal"><p>确定删除《{deletePaper.title}》及其关联证据和实验记录？此操作无法撤销，原始上传文件请自行保留备份。</p><div className="modal-actions"><button className="button secondary" disabled={busy==='delete'} onClick={()=>setDeletePaper(null)}>取消</button><button className="button danger" disabled={busy==='delete'} onClick={()=>void removePaper()}>{busy==='delete'?<Spinner/>:<Trash size={16}/>}删除文献</button></div></Modal>}
  {detail&&<Modal error={error} title="文献详情" onClose={()=>setDetail(null)} className="paper-detail-modal">
   <div className="detail-paper-heading"><div className="row"><Tag tone="green">{detail.parser}</Tag>{detail.is_demo&&<Tag tone="amber">合成演示文献</Tag>}<span className="micro muted">{detail.page_count} 页</span></div><h2>{detail.title}</h2><p>{detail.authors.join(' · ')||'作者未识别'}{detail.year?' · '+detail.year:''}</p>
    <div className="row detail-actions">{detail.file_url&&<a className="button secondary small" href={detail.file_url} target="_blank" rel="noreferrer"><ArrowSquareOut size={15}/>打开原文</a>}<button className="button secondary small" disabled={!!busy} onClick={()=>void extractPaper('rule')}>{busy==='extract'?<Spinner/>:<ArrowClockwise size={15}/>}生成规则候选</button><button className="button secondary small" disabled={!!busy} onClick={()=>void beginManualCandidate()}><PencilSimple size={15}/>从原文建立人工候选</button><button className="button secondary small" disabled={!!busy||!health?.providers.llm_configured} title={!health?.providers.llm_configured?'请先配置后端模型服务':'将发起模型请求，可能产生调用费用'} onClick={()=>void extractPaper('llm')}><Robot size={15}/>模型候选提取</button></div>
    <div className="extraction-scope-controls"><label className="field-label">提取页码<input aria-label="提取页码" value={extractPages} onChange={event=>setExtractPages(event.target.value)} placeholder="留空为全文，例如 1,3-5" disabled={!!busy} maxLength={200}/><small>使用原文页码，指定时最多 25 页。</small></label><label className="field-label">最多结果数<input aria-label="最多结果数" type="number" min="1" max="30" step="1" value={extractMaxResults} onChange={event=>setExtractMaxResults(event.target.value)} disabled={!!busy}/><small>1 至 30 项；有界结果不表示全文完整。</small></label></div>
    <label className="reparse-option"><input type="checkbox" checked={reparse} onChange={event=>setReparse(event.target.checked)} disabled={!!busy}/>重新解析原始文件后生成候选<span>先校验文件 SHA256；接受前保留现有证据和实验</span></label>
    <p className="micro muted extraction-boundary">所有重新提取均先生成候选，接受后追加，不覆盖人工修正。模型提取会调用已配置模型。</p>
    {busy==='extract'&&<div className="operation-status" role="status"><Spinner/><div><strong>正在生成候选 · {elapsed} 秒</strong><span>提取和来源校验尚未完成，既有研究记录保持不变。</span></div><button className="button secondary small" onClick={cancelOperation}>停止等待</button></div>}
   </div>
   <WarningNotes warnings={detail.warnings}/>{detail.error&&<div className="alert error"><WarningCircle size={18}/>{detail.error}</div>}
   {!!detail.extraction_candidates?.length&&<section className="candidate-review"><div className="subsection-heading"><h3>提取候选与人工审阅</h3><span>{detail.extraction_candidates.filter(item=>item.status==='pending').length} 批待审阅</span></div>
    <p className="muted">逐项检查实验配置、数值和字段引文。接受只表示纳入实验库，后续比较仍会检查条件与证据。</p>
    {detail.extraction_candidates.map(candidate=>{const chosen=candidateSelection[candidate.id]??candidate.experiments.map(exp=>exp.id);return <details key={candidate.id} className="candidate-batch" open={candidate.status==='pending'?true:undefined}><summary><span>{candidate.mode==='manual'?'人工':candidate.mode==='llm'?'模型':'规则'}候选 · {candidate.experiments.length} 项{candidate.reparsed?' · 已重新解析':''}</span><Tag tone={candidate.status==='pending'?'amber':'neutral'}>{candidate.status==='pending'?'待审阅':candidate.status==='accepted'?'已接受':'已拒绝'}</Tag><small>{formatDate(candidate.created_at)}</small></summary>
     {candidate.extraction_scope?<p className="candidate-extraction-scope">{candidate.extraction_scope.pages?.length?`原文第 ${candidate.extraction_scope.pages.join('、')} 页`:`全文范围 · ${candidate.extraction_scope.total_pages} 页`} · 最多 {candidate.extraction_scope.max_results} 项{candidate.extraction_scope.truncated?' · 已达到展示上限':''}。完整性未评估，不能将这些候选视为全文实验清单。</p>:<p className="candidate-extraction-scope">{candidate.mode==='manual'?'人工选择原文建立，未调用模型；此候选不代表全文实验清单。':'旧候选未记录提取范围，不能据此判断全文完整性。'}</p>}
     {candidate.stale&&<div className="alert warning"><WarningCircle size={17}/><span>生成候选后实验已变更。请重新提取，避免依据过期状态采纳。</span></div>}
     {!candidate.experiments.length?<p className="candidate-empty">本批未发现有充分来源关联的实验。可检查原文证据、尝试重新解析；不能据此判断论文没有实验。</p>:candidate.experiments.map(exp=><div className="candidate-item" key={exp.id}>{candidate.status==='pending'&&<label className="checkbox-label"><input type="checkbox" aria-label={'接受候选：'+exp.name} checked={chosen.includes(exp.id)} disabled={!!busy||candidate.stale} onChange={()=>setCandidateSelection(current=>({...current,[candidate.id]:chosen.includes(exp.id)?chosen.filter(id=>id!==exp.id):[...chosen,exp.id]}))}/>选入实验库</label>}{experimentCard(exp,candidate)}</div>)}
     {candidate.status==='pending'&&<div className="candidate-actions"><span>已选 {chosen.length} / {candidate.experiments.length} 项</span><button className="button secondary small" disabled={!!busy} onClick={()=>void reviewCandidate(candidate,'reject')}>拒绝本批</button><button className="button primary small" disabled={!!busy||!chosen.length||candidate.stale} onClick={()=>void reviewCandidate(candidate,'accept')}>{busy==='candidate'?<Spinner/>:<Check size={15}/>}接受所选候选</button></div>}
    </details>;})}
   </section>}
   <div className="segmented-tabs detail-tabs"><button className={detailTab==='experiments'?'active':''} onClick={()=>setDetailTab('experiments')}>已保存实验<span>{detail.experiments.length}</span></button><button className={detailTab==='evidence'?'active':''} onClick={()=>setDetailTab('evidence')}>原文证据<span>{detail.evidence.length}</span></button></div>
   {detailTab==='experiments'?detail.experiments.length?<div className="experiment-list">{detail.experiments.map(exp=>experimentCard(exp))}</div>:<Empty icon={TestTube} title="尚未保存实验记录"><p>先生成并审阅提取候选，或在原文证据中检查论文内容。规则无法覆盖所有论文结构。</p></Empty>:detail.evidence.length?<div className="detail-evidence-list">{detail.evidence.map((item,index)=><button key={item.id} className="detail-evidence-item" onClick={()=>openEvidence(item,detail.evidence)}><div className="row between"><strong>证据 {String(index+1).padStart(2,'0')}</strong><span>第 {item.page} 页 · {item.section||'正文'} <ArrowSquareOut size={13}/></span></div><p>{item.text}</p></button>)}</div>:<Empty icon={FileMagnifyingGlass} title="没有可读取的原文证据"><p>请检查文件是否为扫描件或是否解析失败。</p></Empty>}
  </Modal>}
  {editExperiment&&<Modal error={error} title={manualCandidate?'从原文建立人工候选':'修正实验信息'} onClose={()=>{if(busy!=='save')setEditExperiment(null);}} className="edit-modal">
   <p className="muted">{manualCandidate?'填写原文支持的实验字段并分别关联英文引文；可缩短引文，但必须保持原文逐字摘录。未知项留空。保存后仍需审阅采纳，不调用模型。':'请先核对原文。保存会校验打开表单时的版本；字段来源只表示人工关联，不代表已验证语义。原记录会归档，比较报告需重新生成。'}</p>{editConflict&&<div className="alert warning edit-conflict"><WarningCircle size={18}/><span>该记录已在别处修改，本次输入保留且未覆盖服务器记录。请先保留需要的内容，再重新载入最新版本。</span><button className="button secondary small" disabled={!!busy} onClick={()=>void beginEdit(editExperiment)}>放弃本次输入并重新载入</button></div>}
   <form key={editExperiment.id+':'+editRevision} onSubmit={saveExperiment}><div className="edit-fields">{[['name','实验名称'],['task','研究任务'],['method','方法 / 模型'],['dataset','数据集'],['split','数据划分'],['sample_size','样本量'],['metric','评价指标'],['value','结果数值'],['unit','单位']].map(([key,label])=><label className="field-label" key={key}>{label}<input name={key} defaultValue={editExperiment[key as keyof Experiment] as string|number??''} required={key==='name'||(manualCandidate&&key==='value')} type={key==='value'?'number':'text'} step={key==='value'?'any':undefined} maxLength={key==='metric'||key==='sample_size'?200:key==='unit'?100:500}/></label>)}
    <label className="field-label edit-conditions">实验条件<textarea name="conditions" rows={5} defaultValue={Object.entries(editExperiment.conditions??{}).map(([key,value])=>key+': '+value).join('\n')} placeholder={'模型配置: 单模型\n预处理: 标准化\n每行一项，使用英文冒号分隔'}/><small>补充模型配置、训练方案、评估协议等条件；不确定的信息请留空。</small></label>
   </div>
   <section className="edit-source-panel"><h3>关联字段原文</h3><p>每个字段分别选择来源；实验条件需有支持条件名称和内容的证据。修改数值后请重新核对来源。</p><div className="edit-source-controls"><label className="field-label">字段<select aria-label="待关联证据字段" value={editSourceField} onChange={e=>setEditSourceField(e.target.value)}>{Object.entries(fieldNames).map(([field,label])=><option key={field} value={field}>{label} · {editFieldEvidence[field]?.length??0} 条</option>)}</select></label><label className="field-label">查找原文<input aria-label="查找字段来源" value={editSourceQuery} onChange={e=>setEditSourceQuery(e.target.value)} placeholder="页码、章节或原文关键词"/></label></div>
    <div className="edit-source-options">{editSources.filter(item=>(item.page+' '+item.section+' '+item.text).toLowerCase().includes(editSourceQuery.toLowerCase())).slice(0,60).map(item=><div className="edit-source-item" key={item.id}><label><input type="checkbox" aria-label={'关联第 '+item.page+' 页证据 '+item.id} checked={(editFieldEvidence[editSourceField]??[]).includes(item.id)} onChange={()=>setEditFieldEvidence(current=>{const ids=current[editSourceField]??[];return {...current,[editSourceField]:ids.includes(item.id)?ids.filter(id=>id!==item.id):[...ids,item.id]};})}/><span><strong>第 {item.page} 页 · {item.section||'正文'}</strong><small>{item.text.slice(0,180)}</small></span></label>{manualCandidate&&(editFieldEvidence[editSourceField]??[]).includes(item.id)&&<label className="field-label manual-quote">逐字原文引文<textarea aria-label={'字段原文引文 '+editSourceField+' '+item.id} rows={4} value={manualQuotes[editSourceField]?.[item.id]??item.text} onChange={e=>{const quote=e.target.value;setManualQuotes(current=>({...current,[editSourceField]:{...current[editSourceField],[item.id]:quote}}));}}/></label>}<button className="text-button small" type="button" onClick={()=>openEvidence(item)}>原文<ArrowSquareOut size={12}/></button></div>)}</div>
    <small className="muted">显示最多 60 条；用关键词或页码缩小范围。当前字段关联 {editFieldEvidence[editSourceField]?.length??0} 条。</small>
   </section>
   <div className="modal-actions"><button className="button secondary" type="button" disabled={busy==='save'} onClick={()=>setEditExperiment(null)}>取消</button><button className="button primary" disabled={busy==='save'||editConflict}>{busy==='save'?<Spinner/>:<Check size={16}/>}{manualCandidate?'保存为待审阅候选':'保存修正与来源'}</button></div></form>
  </Modal>}
  {experimentHistory&&<Modal error={error} title="实验修改历史" onClose={()=>setExperimentHistory(null)} className="paper-detail-modal experiment-history-modal"><div className="detail-paper-heading"><h2>{experimentHistory.current.name}</h2><p>只读查看当前记录与保存前的历史版本。历史字段不会恢复或覆盖当前实验；引用使用保留的来源摘录。</p></div><div className="experiment-history-list"><h3>当前记录</h3>{experimentCard(experimentHistory.current,undefined,{sources:experimentHistory.sources,origin:{label:'当前实验记录',papers:[experimentHistory.paper],historical:false}})}<h3>历史版本 · {experimentHistory.entries.length} 条</h3>{experimentHistory.entries.length?experimentHistory.entries.map(entry=><details className="experiment-history-entry" key={entry.id}><summary>{formatDate(entry.created_at)} · {new Date(entry.created_at).toLocaleTimeString('zh-CN')}<span>{entry.reason==='manual_edit'?'人工修改前记录':entry.reason==='replacement'?'替换前记录':entry.reason}</span></summary>{experimentCard(entry.experiment,undefined,{sources:experimentHistory.sources,origin:{label:'实验历史版本 · '+formatDate(entry.created_at),papers:[experimentHistory.paper],historical:true}})}</details>):<p className="muted">尚无已归档的修改。保存人工修正时会先保留旧版本。</p>}</div></Modal>}
  {activeEvidence&&<Modal error={error} title="原文证据" onClose={()=>setActiveEvidence(null)} className="evidence-drawer"><div className="evidence-drawer-meta"><Tag tone={activeEvidence.origin?.historical?'amber':'green'}><Link size={12}/>{activeEvidence.origin?.historical?'历史原文摘录':'来源可追溯'}</Tag><span className="micro muted">第 {activeEvidence.item.page} 页</span></div><h3>{evidencePaper?.title??'来源文献'}</h3>{activeEvidence.origin&&<p className="evidence-origin-note">{activeEvidence.origin.label}{activeEvidence.origin.historical?' · 只读保存版本，非当前判断':''}</p>}<div className="evidence-section-label">{activeEvidence.item.section||'正文片段'} · {activeEvidence.item.source_type==='table'?'表格证据':'文本证据'}</div><section className="field-quote-panel">{activeEvidence.fieldContext&&<><h4>{activeEvidence.fieldContext.label}{activeEvidence.fieldContext.kind==='citation'?'':' · 字段引文'}</h4>{activeEvidence.fieldContext.quotes.filter(ref=>ref.id===activeEvidence.item.id).map((ref,index)=><blockquote key={index}>{ref.quote}</blockquote>)}{!activeEvidence.fieldContext.quotes.some(ref=>ref.id===activeEvidence.item.id)&&<p>此记录仅保存了证据关联，请在下方原文中人工定位该字段。</p>}<small>{activeEvidence.fieldContext.kind==='citation'?'来源片段按服务器绑定恢复原文；精确引用只说明文字来源，不保证命题语义和实验归属正确。':'字段引文用于定位来源。文字出现不等于支持该字段，实验归属和语义支持仍需人工复核。'}</small></>}</section><blockquote className="evidence-quote">{activeEvidence.item.text}</blockquote><div className="evidence-id">证据标识 <code>{activeEvidence.item.id}</code></div>{originalState==='available'?<a className="button primary evidence-open" href={(evidencePaper?.file_url??'/api/papers/'+activeEvidence.item.paper_id+'/file')+'#page='+activeEvidence.item.page} target="_blank" rel="noreferrer"><ArrowSquareOut size={16}/>打开原始文献 · 第 {activeEvidence.item.page} 页</a>:<div className="evidence-file-status alert warning" role="status">{originalState==='checking'?<><Spinner/><span>正在检查原始文件；保存的摘录可继续阅读。</span></>:<><WarningCircle size={18}/><span>{originalError||'原始文件暂时无法访问，保存的摘录仍可阅读。'}</span></>}</div>}{activeEvidence.item.bbox&&<p className="micro muted">已保留页面坐标：{activeEvidence.item.bbox.map(n=>Math.round(n)).join(', ')}</p>}{originalState==='available'&&/\.pdf$/i.test(evidencePaper?.filename??'')&&<PaperPagePreview key={`${activeEvidence.item.paper_id}:${activeEvidence.item.page}`} paperId={activeEvidence.item.paper_id} page={activeEvidence.item.page} fileUrl={(evidencePaper?.file_url??'/api/papers/'+activeEvidence.item.paper_id+'/file')+'#page='+activeEvidence.item.page}/>}{activeEvidence.list.length>1&&<div className="related-evidence"><h4>本次关联证据 <span>{activeEvidence.list.length}</span></h4>{activeEvidence.list.map((item,index)=><button className={item.id===activeEvidence.item.id?'active':''} key={item.id} onClick={()=>setActiveEvidence({...activeEvidence,item})}><span>{String(index+1).padStart(2,'0')}</span><div><strong>第 {item.page} 页 · {item.section||'正文'}</strong><p>{item.text}</p></div><CaretRight size={15}/></button>)}</div>}<div className="evidence-boundary"><ShieldCheck size={17}/><p>原文片段用于追溯来源，仍需结合全文和实验条件理解。</p></div></Modal>}
 </div>;
}
